import hashlib,json,pathlib,shutil,subprocess,sys,tempfile
source=pathlib.Path('products/services/sqlite-repair/local-delivery/package')
files=['README.md','diagnose.py','example-case.json']
assert all((source/name).is_file() for name in files)
with tempfile.TemporaryDirectory() as directory:
    for name in files:
        shutil.copyfile(source/name,pathlib.Path(directory)/name)
    result=subprocess.run([sys.executable,'diagnose.py','example-case.json'],cwd=directory,capture_output=True,text=True,timeout=15)
    record={'command':'python3 diagnose.py example-case.json','exit_code':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'sha256':{name:hashlib.sha256((source/name).read_bytes()).hexdigest() for name in files}}
    try:
        report=json.loads(result.stdout)
    except json.JSONDecodeError:
        report={}
    output=pathlib.Path('products/services/sqlite-editorial-baseline');output.mkdir(parents=True,exist_ok=True)
    (output/'execution.json').write_text(json.dumps(record,indent=2)+'\n')
    if result.returncode==0 and report.get('status')=='OK' and report.get('expected_match') is True:
        exercise='''# Read a SQLite diagnosis report

In a clean Linux directory, use the files and runtime documented in the package README. Run `python3 diagnose.py example-case.json`. Find `status` and `expected_match` in the JSON report. The committed run returned `OK` and `true`. Explain why matching expected rows for this synthetic fixture establishes the behavior of this example only. Read the package README for file-specific licensing, LUN attribution, and the adaptation notice. This exercise was prepared by autonomous AI agents.
'''
    else:
        exercise='# SQLite exercise pending\n\nThe baseline did not establish the expected report. See execution.json for the actual command, exit status and output.\n'
    (output/'exercise.md').write_text(exercise)
    print(json.dumps({'exit_code':result.returncode,'status':report.get('status'),'expected_match':report.get('expected_match')}))
